INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(939, 'koKR', 'Flet Xavarica', 'Przyglądasz się prostemu drewnianemu fletowi, który $gpodniosłeś:podniosłaś; po pokonaniu Xavarica.$B$BSękate drewno wydaje się solidne, ale gdy obracasz flet w dłoniach, spirale i wzory na jego powierzchni zdają się wirować i poruszać. Nagle ogarnia cię poczucie grozy...$B$BPotrząsasz głową, $gpewien:pewna;, że umysł płata ci figle.$B$BMożliwe, że inne satyry mają przy sobie wskazówki dotyczące twojego znaleziska. Zanieś to, co $gznalazłeś:znalazłaś;, druidce Eridan Błękitny Wiatr, która mieszka w południowej części Spaczonej Kniei.', 'Zanieś Flet Xavarica i 5 próbek spaczowięzi Nefrytowego Ognia Eridan Błękitny Wiatr w południowej części Spaczonej Kniei.', '', 'Wróć do Eridan Błękitny Wiatr w Szmaragdowym Sanktuarium w Spaczonej Kniei.', '', '', '', '', 0),
(996, 'koKR', 'Skażony wiatrokwiat', '', '', '', 'Wróć do skażonego wiatrokwiatu w Spaczonej Kniei.', '', '', '', '', 0),
(998, 'koKR', 'Skażony wiatrokwiat', '', '', '', 'Wróć do skażonego wiatrokwiatu w Spaczonej Kniei.', '', '', '', '', 0),
(1514, 'koKR', 'Skażony wiatrokwiat', '', '', '', 'Wróć do skażonego wiatrokwiatu w Spaczonej Kniei.', '', '', '', '', 0),
(3942, 'koKR', 'Wspomnienie Linkena', 'Och... Linken? No, zabawny z niego gość. Kiedy tu przybył, mamrotał o najróżniejszych dziwnych rzeczach. Pewnie nieźle oberwał w głowę, tak mi się zdaje.$B$BAle jedna rzecz, którą powiedział, utkwiła mi w pamięci: że robił jakiś totem; mówił, że musi porozmawiać z kimś o imieniu Eridan Błękitny Wiatr... w miejscu zwanym Spaczoną Knieją, chyba?$B$BWątpię jednak, żeby teraz wiele ci powiedział. Jeśli chcesz wiedzieć więcej, może $gsam:sama; poszukasz Eridan?', 'Odszukaj Eridan Błękitny Wiatr w południowej części Spaczonej Kniei.', '', '', '', '', '', '', 0),
(4005, 'koKR', 'Aquementas', 'Zabierz tę torbę z zapasami do Tanaris. Udaj się do Zatoczki Zaginionego Takielarza i poszukaj kręgu kamieni.$B$BSekretem jest najdalej wysunięty na wschód półwysep...$B$BTylko z tego kręgu czytaj z Księgi Aquora; przyzwij jedyne stworzenie, które potrafi przemienić zebrane przez ciebie przedmioty w totem do walki z Żarobiegiem.$B$BAquementas nie będzie zadowolony, że go obudzono, ale pamiętaj: musisz pozostać w kręgu, by przemienił przedmioty.', 'Zabierz Księgę Aquora, Srebrzyste pazury i Serce żelaznego drzewa do Tanaris.$B$BUżyj Księgi Aquora, by przyzwać Aquementasa.$B$BGdy będziesz mieć gotowy totem, zanieś go J.D. Collie w Schronieniu Marshala.', '', 'Wróć do J.D. Collie w Kraterze Un\'Goro.', '', '', '', '', 0),
(4084, 'koKR', 'Srebrne serce', 'Nie znam tego, o kim mówisz, $N.$B$BAle nie martw się; jeśli twój przyjaciel wyruszył, by mnie odnaleźć, wiem, czego pragnął.$B$BW sercu Krateru Un\'Goro mieszka zło w najczystszej postaci. To zło przybrało postać żywiołaka zwanego Żarobiegiem... chronionego aurą, której nikt nie potrafi rozproszyć...$B$BNikt... prócz tych, którzy mają dość mocy, by to zrobić. Mogę cię nauczyć tej mocy, $N.$B$BNajpierw jednak zrób, o co proszę. Zbierz 11 srebrzystych pazurów i 1 serce żelaznego drzewa od stworzeń w Spaczonej Kniei, a potem wróć.', 'Zbierz 11 srebrzystych pazurów i 1 serce żelaznego drzewa dla Eridan Błękitny Wiatr w Spaczonej Kniei.', '', 'Wróć do Eridan Błękitny Wiatr w Szmaragdowym Sanktuarium w Spaczonej Kniei.', '', '', '', '', 0),
(4101, 'koKR', 'Oczyszczanie Spaczonej Kniei', 'Rośliny dają życie Spaczonej Kniei, a jednak i one cierpią od skażenia. Znam sposoby, by je oczyścić, ale nie mogę dzielić się taką wiedzą z tymi, których nie znam lub którym nie ufam. Udowodnij mi, że naprawdę wesprzesz sprawę Kręgu Cenariona!$B$BNa północy leży Pieczara Żelaznych Drzew. Żywiołaki Wypaczonego Drzewa, które tam przebywają, są już poza wszelką nadzieją na oczyszczenie. Proszę cię, przynieś mi ich sok – zwany krwawym bursztynem – bym mogła go zbadać w nadziei na ocalenie innych form życia w tej krainie.', 'Przynieś 15 krwawych bursztynów Arathandris Srebrne Niebo w Spaczonej Kniei.', '', 'Wróć do Arathandris Srebrne Niebo w Spaczonej Kniei.', '', '', '', '', 0),
(4102, 'koKR', 'Oczyszczanie Spaczonej Kniei', 'Rośliny dają życie Spaczonej Kniei, a jednak i one cierpią od skażenia. Znam sposoby, by je oczyścić, ale nie mogę dzielić się taką wiedzą z tymi, których nie znam lub którym nie ufam. Udowodnij mi, że naprawdę wesprzesz sprawę Kręgu Cenariona!$B$BNa północy leży Pieczara Żelaznych Drzew. Żywiołaki Wypaczonego Drzewa, które tam przebywają, są już poza wszelką nadzieją na oczyszczenie. Proszę cię, przynieś mi ich sok – zwany krwawym bursztynem – bym mogła go zbadać w nadziei na ocalenie innych form życia w tej krainie.', 'Przynieś 15 krwawych bursztynów Maybess Rzecznej Bryzie w Spaczonej Kniei.', '', 'Wróć do Maybess Rzecznej Bryzy w Spaczonej Kniei.', '', '', '', '', 0),
