INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(2671, 'koKR', 'Simone Uwodzicielka:$B$BSimone znajdziesz w Kraterze Un\'Goro, który plugawi swoją obecnością. Nie daj się zwieść jej przebraniu. Zbliż się do niej ostrożnie i wyzwij ją do walki.', 0),
(2672, 'koKR', 'Klinfran Obłąkany:$B$BKlinfran wędruje po Płonących Stepach. Zbliż się do niego ostrożnie i zmuś go, by ukazał swoją prawdziwą postać.', 0),
(2673, 'koKR', 'Solenor Pogromca:$B$BW suchym krajobrazie Silithusu czai się ten nikczemnik, Solenor Pogromca. Bez wątpienia w przebraniu, z pewnością groźny. Podejdź do niego i zmuś go do przemiany.', 0),
(2674, 'koKR', 'Artorius Niosący Zagładę:$B$BArtorius niesie skażenie i zagładę wszystkiemu, czego dotknie w Zimozdroju. Znajdź go i zabij.', 0),
(2675, 'koKR', 'Strzeż się, $głowco:łowczyni; – z tymi demonami trzeba walczyć na ich warunkach. Jeśli uznają, że nie mają nad tobą przewagi, uciekną.$B$BIDŹ $gSAM:SAMA;.', 0);
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(11016, 0, 0, 'koKR', 'Jestem gotowa, $N. Znajdźmy mój ekwipunek i wynośmy się stąd. Chyba wiem, gdzie jest.'),
(11016, 2, 0, 'koKR', 'Patrz! Tam!'),
(11016, 3, 0, 'koKR', 'Nie powstrzymasz mnie przed ucieczką!'),
(11018, 3, 0, 'koKR', 'Nie powstrzymasz mnie przed ucieczką!');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(4839, 'koKR', '', 'Wiem, że tym razem się uda...', 0),
(4840, 'koKR', '', 'To będzie mój najlepszy eksperyment!', 0),
(4841, 'koKR', '', 'A teraz, jeśli dodam te żółte...', 0),
(4842, 'koKR', '', 'Wiem, że tym razem się uda... Moje ostatnie 13 prób to był tylko trening!', 0),
(4843, 'koKR', '', 'Ech... Moje eksperymenty nigdy się nie udają. Może powinnam wrócić w dół rzeki.', 0),
(4846, 'koKR', '', '%s zaczyna łączyć ze sobą kryształy w różnych kolorach.', 0),
(4847, 'koKR', '', 'Chyba... chyba działa!', 0),
(4852, 'koKR', '', 'AUĆ! Nie tak miało być!', 0),
(4853, 'koKR', '', 'No trudno... Może następnym razem.', 0),
(5171, 'koKR', '', 'Mam na imię J.D. i naprawdę niewiele mogę ci powiedzieć o tym, jak się tu znalazłam, ale mogę ci powiedzieć, że ten obóz jest teraz moim domem!$B$BSpędzam czas na badaniu dziwnych kryształów, które można znaleźć w całym kraterze. $GMusiałeś:Musiałaś; widzieć kilka po drodze. Słuchaj, może jakieś $gpodniosłeś:podniosłaś;?', 0),
(5185, 'koKR', '', 'Dzięki tobie możemy teraz odkryć sekrety kryształów i tajemniczych pylonów, $N. Jeśli kiedykolwiek będziesz potrzebować więcej informacji, wróć i odwiedź mnie znowu!', 0),
(5186, 'koKR', 'Opowiedz mi więcej o Wschodnim kryształowym pylonie.', 'Opowiedz mi więcej o Wschodnim kryształowym pylonie.', 0),
(5188, 'koKR', 'Opowiedz mi więcej o Północnym kryształowym pylonie.', 'Opowiedz mi więcej o Północnym kryształowym pylonie.', 0),
(5190, 'koKR', 'Opowiedz mi więcej o Zachodnim kryształowym pylonie.', 'Opowiedz mi więcej o Zachodnim kryształowym pylonie.', 0),
(5191, 'koKR', '$GZgubiłem:Zgubiłam; Instrukcję obsługi kryształowego pylonu i potrzebuję nowej.', '$GZgubiłem:Zgubiłam; Instrukcję obsługi kryształowego pylonu i potrzebuję nowej.', 0),
(5192, 'koKR', '', 'Wschodni pylon przyjmuje kryształy niebieskie, żółte i zielone.$B$BSkupia się na energii, którą można wytworzyć, używając niebieskich kryształów jako głównego źródła mocy. Możliwe są dwa efekty: jeden zwiększa duchowość, a drugi tworzy raniącą tarczę.$B$BKryształowa siła wymaga kryształów niebieskich i zielonych. Zwiększy twoją duchowość.$B$BKryształowa iglica wymaga kryształów niebieskich i żółtych. Utworzy tarczę, która rani atakujących.\n', 0),
(5193, 'koKR', '', 'Północny pylon przyjmuje kryształy żółte, czerwone i zielone.$B$BSkupia się na energii, którą można wytworzyć, używając żółtych kryształów jako głównego źródła mocy. Możliwe są dwa efekty: jeden zadaje obrażenia, a drugi je niweluje.$B$BKryształowy ładunek wymaga kryształów czerwonych i żółtych. Wywoła potężny wybuch, który ogłuszy twoich wrogów.$B$BKryształowe odnowienie wymaga kryształów żółtych i zielonych. Zapewni ci leczącą aurę.', 0),
(5194, 'koKR', '', 'Zachodni pylon przyjmuje kryształy czerwone, zielone i niebieskie.$B$BPylon skupia się na energii, którą można wytworzyć, używając czerwonych kryształów jako głównego źródła mocy. Możliwe są dwa efekty: jeden zwiększa twoją ochronę przed obrażeniami, a drugi osłabia obronę wroga.$B$BKryształowa osłona wymaga kryształów czerwonych i zielonych. Zwiększy twój pancerz.$B$BKryształowy plon wymaga kryształów niebieskich i czerwonych. Może obniżyć pancerz wybranego celu.', 0),
(5195, 'koKR', '', 'Jasne, $N. Masz tu drugą.', 0),
(5204, 'koKR', '', 'Te niegdyś piękne lasy cierpią pod straszliwą klątwą! Spaczające siły wykrzywiają tutejsze życie, czyniąc z niego cień dawnego siebie. Jeśli nie jesteś sługą tego skażenia, może pomożesz mi odzyskać Spaczoną Knieję!', 0),
(5206, 'koKR', '', '„Taurahe?”$B$BTaureńska druidka patrzy na ciebie wyczekująco, ale wyraźnie nie jesteście w stanie porozumieć się słowami. Niezrażona, wskazuje na siebie i się uśmiecha. Wskazuje na ciebie i znów się uśmiecha. W końcu kilka razy pokazuje ścieżkę prowadzącą na południe.$B$BMoże chce ci dać do zrozumienia, że dalej przy drodze jest druid, z którym możesz porozmawiać?\n', 0),
(5208, 'koKR', '', 'Te niegdyś piękne lasy cierpią pod straszliwą klątwą! Spaczające siły wykrzywiają tutejsze życie, czyniąc z niego cień dawnego siebie. Jeśli nie jesteś sługą tego skażenia, może pomożesz mi odzyskać Spaczoną Knieję!', 0),
(5209, 'koKR', '', '„Darnassae?”$B$BDruidka z rasy nocnych elfów patrzy na ciebie wyczekująco, ale wyraźnie nie jesteście w stanie porozumieć się słowami. Niezrażona, wskazuje na siebie i się uśmiecha. Wskazuje na ciebie i znów się uśmiecha. W końcu kilka razy pokazuje ścieżkę prowadzącą na północ.$B$BMoże chce ci dać do zrozumienia, że dalej przy drodze jest druid, z którym możesz porozmawiać?', 0),
(5241, 'koKR', '', 'W Spaczonej Kniei rosną rośliny, które można uratować przed skażeniem, nakładając na nie cenariońską maść dla roślin. Umiem zrobić tę maść z kilku różnych rodzajów przedmiotów; zależnie od twoich umiejętności może się okazać, że masz kilka sposobów, by mi pomóc.$B$BDo pracy tutaj będzie ci też potrzebna Latarnia Cenariona; to urządzenie, które pozwala dostrzec skazę i skażenie natury, których gołe oko nie zauważy.', 0),
(5243, 'koKR', 'Potrzebuję Latarni Cenariona.', 'Potrzebuję Latarni Cenariona.', 0),
(5244, 'koKR', '', 'Oto latarnia dla ciebie, $N. Musisz ją mieć przy sobie, jeśli chcesz znaleźć skażone przedmioty, których potrzebujemy.', 0),
(5245, 'koKR', '', 'Oto latarnia dla ciebie, $N. Musisz ją mieć przy sobie, jeśli chcesz znaleźć skażone przedmioty, których potrzebujemy.', 0),
(5287, 'koKR', '', 'No dobrze, zobaczmy... Jeśli mam rację, to... Hmmm...', 0),
(5288, 'koKR', '', 'Niebieski plus czerwony... Przewiduję...', 0),
(5289, 'koKR', '', '$N, to jest to! W końcu to rozgryzłam!', 0),
(5384, 'koKR', 'Jakie rośliny w Spaczonej Kniei mogą być skażone?', 'Jakie rośliny w Spaczonej Kniei mogą być skażone?', 0),
(5945, 'koKR', '', 'Bardzo jestem ciekawa, co zdziała ta próbka wody!', 0),
(5946, 'koKR', '', '%s wylewa skażoną wodę na kota.', 0),
(5947, 'koKR', '', 'Haha! Idealnie!', 0),
(6432, 'koKR', '', 'Szmaragdowy Krąg stara się uleczyć zranioną ziemię Spaczonej Kniei. Choć kraina nosi nazwę tego samego, co ją skaziło, mamy nadzieję, że pewnego dnia zdołamy wyplenić z niej skażenie.', 0),
(6435, 'koKR', '', 'Witaj, $N. Jestem Jessir Księżycowy Łuk. Przybyłam z Darnassus, by odnaleźć dwoje przyjaciół, którzy przyszli do Spaczonej Kniei szukać śladów Rady Cieni.$B$BWygląda na to, że te plugawe istoty, które przyznają się do sprowadzenia wielu cierpień na rasę orków, próbują odzyskać część swojej mocy.$B$BMoi przyjaciele udali się do Jaedenaru, by ustalić, co się tam dzieje.$B$BSpodziewałam się, że zastanę ich tutaj, ale spóźniają się już o kilka dni.', 0),
(6456, 'koKR', '', 'O rety! Spójrz na to... te wszystkie świece. Na pewno służą do jakiegoś strasznego rytuału albo mrocznego przyzywania. Lepiej się pospieszmy!', 0),
(6800, 'koKR', '', 'Tak zimno... i jestem taka głodna.$B$BMój biedny przyjacielu, mam nadzieję, że zaznałeś spokoju. Nie mogę znieść myśli o tym, co mogli ci zrobić.$B$BTy! Tak, ty! Proszę, musisz mi pomóc uciec. Jeden z nich ma klucz, możesz go znaleźć? Wiem, że go mają. Jeśli go zdobędziesz, pomożesz mi się stąd wydostać. Trey pewnie już nie żyje, ale jeszcze jest czas! Proszę, pomożesz mi?', 0),
(6804, 'koKR', '', 'Już $gwyświadczyłeś:wyświadczyłaś; mi wielką przysługę, $N. Dziękuję ci za to.$B$BNajmniej, co mogę teraz zrobić, to powiedzieć ci, co mnie tu sprowadziło: razem z moim wieloletnim przyjacielem, Treyem Kuźnią Światła, przybyliśmy do Jaedenaru, by przyjrzeć się Radzie Cieni, ale zaskoczyli nas nieprzygotowanych. Zabrali Treya w głąb Warowni Cienia, a mnie zamknęli tutaj, odebrawszy nam cały ekwipunek... Wciąż słyszę jego krzyki z dołu, $N. Były... nieludzkie. Nie wiem, co mu zrobili, ale zapłacą za to. ', 0),
(6805, 'koKR', '', 'Gdy przyglądasz się klatce i uwięzionej w niej nocnej elfce, ogarnia cię dziwne uczucie déjà vu. Z jakiegoś powodu kobieta nie patrzy ci w oczy – zupełnie jakby cię tu nie było.', 0),
(7135, 'koKR', 'Jesteśmy ostatnimi z rasy furbolgów... Plemię Pyskodrzewnych nie uległo skażeniu, a jednak spotyka nas ta sama wrogość ze strony obcych; większość uważa, że to niemożliwe... że mogłyby istnieć furbolgi, które uniknęły skażenia...$B$BRozgniewani na tych, którzy zbyt pochopnie robią sobie wrogów, moi pobratymcy atakują teraz każdego, kto się zbliży; nikomu nie ufają.$B$BAle może, jeśli postarasz się pokazać im swoje pokojowe zamiary, uznają cię za sojusznika.', '', 0),
(7136, 'koKR', 'Jak mogę się wykazać przed furbolgami Pyskodrzewnych?', 'Jak mogę się wykazać przed furbolgami Pyskodrzewnych?', 0),
(7137, 'koKR', 'Musisz znaleźć sposób, by pokazać, że walczycie po tej samej stronie. Choć Pyskodrzewni mogą cię teraz atakować, jeśli wykażesz się wytrwałością, znajdziesz sposób.$B$BPamiętaj, że każdy bezpośredni atak na furbolgi Pyskodrzewnych mocno zmniejszy twoje szanse na zdobycie ich przyjaźni.$B$BDobrze byłoby zacząć od furbolgów Martwego Drewna, których można spotkać w wielu częściach Spaczonej Kniei. Te furbolgi są wrogami plemienia Pyskodrzewnych, a zabijanie ich znacznie poprawi twoją pozycję u Pyskodrzewnych.', '', 0),
(7140, 'koKR', 'Furbolgi Zimospadu, które żyją tu, w Zimozdroju, były niegdyś naszymi sojusznikami... Ale pewnego dnia wszystko się zmieniło.$B$BPopychane dziwnymi żądaniami swojego najwyższego wodza, zaczęły atakować wszystkich, z którymi się zetknęły, także nasze plemię. Teraz trzymają się na uboczu...', '', 0),
(7147, 'koKR', 'Jeśli udowodnisz, że jesteś prawdziwym sojusznikiem, może rozważę, czy cię szkolić...', '', 0),
(8366, 'koKR', '', 'Niech ta zła aura zostanie wygnana z tego artefaktu!', 0),
(8367, 'koKR', '', 'Czuję, jak obecność zła odchodzi...', 0),
(9585, 'koKR', 'Masz może jakieś pająki albo żuki, $N? Szybko przebierają nóżkami, ale jeśli okażesz się $gszybszy:szybsza;, przekonasz się, że to prawdziwy przysmak!', '', 0),
(9586, 'koKR', 'Gorzeeki, chcę coś kupić.', 'Gorzeeki, chcę coś kupić.', 0),
(9615, 'koKR', 'To jest to, Chochlisiu. Czuję to! To będzie ten wielki!', '', 0),
(9616, 'koKR', 'Przygotuj się na wspaniałe uderzenie, Chochlisiu!', '', 0),
(9617, 'koKR', 'Wyrzucić mnie chcieli, co!? Pokażę tym nadętym stożkogłowym z Wichrogrodu prawdziwą moc Niby\'ego! PATRZCIE!', '', 0),
(9618, 'koKR', '%s z frustracją potrząsa pięścią.', '', 0),
(9622, 'koKR', 'Ty mały...!', '', 0),
(9624, 'koKR', 'Pokłoń się w mojej obecności, robaku! Z pewnością czujesz, jaką mam nad tobą władzę.', '', 0),
(9625, 'koKR', 'Szukam wielkiego i potężnego czarnoksiężnika.', 'Szukam wielkiego i potężnego czarnoksiężnika.', 0),
(9626, 'koKR', 'Więc $gprzybyłeś:przybyłaś; do Niby\'ego, by poznać sekrety sprowadzania piekielnego sługi z Otchłani.$B$BCisza! Niby wie wszystko!$B$BNiby nie dzieli się tak chętnie taką wiedzą. Najpierw musisz pomóc Niby\'emu w bardzo ważnym zadaniu.', '', 0),
(9627, 'koKR', 'Jakim zadaniu?', 'Jakim zadaniu?', 0),
(9628, 'koKR', 'Na północny wschód od tego obozu jest potężny piekielnik imieniem Kroshius. To z jego powodu Niby tu jest. Kroshius to większy piekielnik – piekielnik, który przetrwał dłużej, niż się spodziewano. Widzisz, żółtodziobie, piekielnik z wielką siłą spada na ziemię, by służyć swemu panu, ale ta siła szybko słabnie. Gdy buzujące płomienie przygasną, piekielnik się rozsypuje.', '', 0),
(9629, 'koKR', 'To wszystko bardzo ciekawe, ale czego właściwie chcesz?', 'To wszystko bardzo ciekawe, ale czego właściwie chcesz?', 0),
(9630, 'koKR', 'Nie przerywaj Niby\'emu, głupcze! Zedrę ci mięso z kości, a z twojego szkieletu zrobię wieszak na płaszcze. Na czym to ja skończyłem? A tak, więc Kroshius przetrwał niemal dziesięć razy dłużej niż zwykły piekielnik. Nie wiem dlaczego, ale jestem pewien, że po odpowiednio długich badaniach zdołałbym to odkryć.$B$BMusisz zdobyć dla mnie Piekielny rdzeń Kroshiusa.', '', 0),
(9631, 'koKR', 'Jak mam to zrobić?', 'Jak mam to zrobić?', 0),
(9632, 'koKR', 'Jeśli mam cię nauczyć sekretów przyzywania piekielnego sługi, musisz zniszczyć Kroshiusa i przynieść mi piekielny rdzeń z jego płonących szczątków. Nie jest to jednak takie proste, jak się wydaje. Kroshius niemal całkiem się wypalił. Musisz na nowo rozpalić jego zwłoki i podnieść go z gruzów. Aby to zrobić, musisz jednak zebrać pewne składniki od innych demonicznych istot.$B$BMój chochlik, Chochliś, wskaże ci drogę.', '', 0),
(9633, 'koKR', 'Kroshius żyje? Kroshius miażdży!', '', 0),
(9634, 'koKR', 'Cofnąć się! Odsunąć się! Piekielnikowi trzeba zostawić dużo miejsca!', '', 0),
(9635, 'koKR', 'POKŁOŃCIE SIĘ WSZECHMOCNEMU! POKŁOŃCIE SIĘ PRZED MOIM PIEKIELNYM NISZCZY... kurczak?', '', 0),
(9638, 'koKR', 'Cisza, sługo! Zemsta będzie moja! Śmierć Wichrogrodowi! Śmierć od kurczaka!', '', 0),
(9735, 'koKR', 'Ty psie! Teraz uwięzię twoją duszę w odłamku i dam cię mojemu chochlikowi do zabawy!', '', 0),
(9736, 'koKR', 'Precz! Naradzam się z upiornymi władcami, a sprawy, które omawiamy, nie są twoją rzeczą!', '', 0),
(9737, 'koKR', 'Z upiornymi władcami? Pewnie chodzi ci o Lorda Zgubodoła. Przesyła pozdrowienia i ma dla ciebie wiadomość...', 'Z upiornymi władcami? Pewnie chodzi ci o Lorda Zgubodoła. Przesyła pozdrowienia i ma dla ciebie wiadomość...', 0),
(9738, 'koKR', '...Wiadomość od Zgubodoła? Jaka to wiadomość? Czy potrzebuje swojego wielkiego doradcy i sługi, Ulatheka? Czy żąda mojej obecności?', '', 0),
(9739, 'koKR', 'Nie, Ulatheku. On zna twój sekret. Wie, że spiskujesz z lordem Hel\'nurathem z Xoroth.', 'Nie, Ulatheku. On zna twój sekret. Wie, że spiskujesz z lordem Hel\'nurathem z Xoroth.', 0),
(9740, 'koKR', 'Co? Ale jak? Nie! To niemożliwe! Byłem tak ostrożny... nie mógł się dowiedzieć!$B$BKłamiesz! Kłamiesz, a teraz zginiesz za swoje oszustwo!', '', 0),
(9741, 'koKR', 'To nie kłamstwo, zdrajco. Zgubodół chce twojego serca, a ja mu je zdobędę.', 'To nie kłamstwo, zdrajco. Zgubodół chce twojego serca, a ja mu je zdobędę.', 0),
(10784, 'koKR', 'Witaj, pradawny. $GZrobiłem:Zrobiłam; wszystko, o co mnie proszono. Teraz proszę, byś dał mi Rhok\'delar.', 'Witaj, pradawny. $GZrobiłem:Zrobiłam; wszystko, o co mnie proszono. Teraz proszę, byś dał mi Rhok\'delar.', 0),
(10785, 'koKR', 'Witaj, pradawny. $GZrobiłem:Zrobiłam; wszystko, o co mnie proszono. Teraz proszę, byś dał mi Lok\'delar.', 'Witaj, pradawny. $GZrobiłem:Zrobiłam; wszystko, o co mnie proszono. Teraz proszę, byś dał mi Lok\'delar.', 0),
(11411, 'koKR', 'Tylko ci, którzy udowodnili, że nie są wrogo nastawieni do Pyskodrzewnych, mogą przejść przez Warownię bez obawy przed atakiem. Czy $gstarałeś:starałaś; się zdobyć nasze zaufanie, $gprzybyszu:przybyszko;?', '', 0),
(11412, 'koKR', 'Czego szukasz, $N?', '', 0),
(11572, 'koKR', 'Gdzie jest Nestor Jasna Włócznia?', 'Gdzie jest Nestor Jasna Włócznia?', 0),
(11573, 'koKR', 'Nestor Jasna Włócznia przechadza się wśród ruin Kel\'Theril w Zimozdroju.', 'Nestor Jasna Włócznia przechadza się wśród ruin Kel\'Theril w Zimozdroju.', 0),
(25677, 'koKR', '$GZgubiłem:Zgubiłam; Flet Pradawnych i potrzebuję nowego, Eridan.', '$GZgubiłem:Zgubiłam; Flet Pradawnych i potrzebuję nowego, Eridan.', 0);
